"""Check authoritative DNAME responses against a fixed unsigned fixture."""

import argparse
import copy
import json
import struct

from upstream_authority import endpoint


def cases():
    # An overflow target is generated by the runner from legal 63-byte labels.
    long_target = ".".join(("a" * 63, "b" * 63, "c" * 63, "d" * 50, "invalid."))
    return [
        (
            "owner-dname",
            "local.example.test.",
            "DNAME",
            0,
            [("local.example.test.", "DNAME", "destination.example.test.", 120)],
        ),
        (
            "owner-other",
            "local.example.test.",
            "TXT",
            0,
            [("local.example.test.", "TXT", '"owner data"', 300)],
        ),
        ("owner-missing", "local.example.test.", "A", 0, []),
        (
            "local-a",
            "www.local.example.test.",
            "A",
            0,
            [
                ("local.example.test.", "DNAME", "destination.example.test.", 120),
                (
                    "www.local.example.test.",
                    "CNAME",
                    "www.destination.example.test.",
                    120,
                ),
                ("www.destination.example.test.", "A", "192.0.2.80", 300),
            ],
        ),
        (
            "local-deep",
            "deep.www.local.example.test.",
            "A",
            0,
            [
                ("local.example.test.", "DNAME", "destination.example.test.", 120),
                (
                    "deep.www.local.example.test.",
                    "CNAME",
                    "deep.www.destination.example.test.",
                    120,
                ),
                ("deep.www.destination.example.test.", "A", "192.0.2.81", 300),
            ],
        ),
        (
            "local-cname",
            "www.local.example.test.",
            "CNAME",
            0,
            [
                ("local.example.test.", "DNAME", "destination.example.test.", 120),
                (
                    "www.local.example.test.",
                    "CNAME",
                    "www.destination.example.test.",
                    120,
                ),
            ],
        ),
        (
            "external",
            "www.external.example.test.",
            "A",
            0,
            [
                ("external.example.test.", "DNAME", "elsewhere.invalid.", 120),
                ("www.external.example.test.", "CNAME", "www.elsewhere.invalid.", 120),
            ],
        ),
        (
            "cname-to-dname",
            "alias.example.test.",
            "A",
            0,
            [
                ("alias.example.test.", "CNAME", "www.local.example.test.", 300),
                ("local.example.test.", "DNAME", "destination.example.test.", 120),
                (
                    "www.local.example.test.",
                    "CNAME",
                    "www.destination.example.test.",
                    120,
                ),
                ("www.destination.example.test.", "A", "192.0.2.80", 300),
            ],
        ),
        (
            "exact-255",
            "12.overflow.example.test.",
            "A",
            0,
            [
                ("overflow.example.test.", "DNAME", long_target, 120),
                ("12.overflow.example.test.", "CNAME", "12." + long_target, 120),
            ],
        ),
        (
            "overflow-256",
            "123.overflow.example.test.",
            "A",
            6,
            [("overflow.example.test.", "DNAME", long_target, 120)],
        ),
        (
            "overflow",
            "1234567890.overflow.example.test.",
            "A",
            6,
            [("overflow.example.test.", "DNAME", long_target, 120)],
        ),
    ]


def validate(case, reply):
    name, _, _, rcode, expected = case
    assert reply["rcode"] == rcode, f"{name}: unexpected rcode {reply['rcode']}"
    assert reply["aa"] and not reply["tc"], f"{name}: incorrect AA/TC"
    assert sorted(reply["answer"]) == sorted(expected), f"{name}: {reply['answer']!r}"
    if name == "owner-missing":
        assert reply["soa"] == [("example.test.", 30)], f"{name}: {reply['soa']!r}"


def uncompressed_dname_targets(wire):
    """Inspect the actual packet, without re-encoding names after parsing."""

    def skip_name(offset, allow_pointer):
        while True:
            if offset >= len(wire):
                raise ValueError("truncated name")
            size = wire[offset]
            offset += 1
            if size & 0xC0 == 0xC0:
                if not allow_pointer or offset >= len(wire):
                    raise ValueError("compressed DNAME target or truncated pointer")
                return offset + 1
            if size & 0xC0 or offset + size > len(wire):
                raise ValueError("invalid label")
            if not size:
                return offset
            offset += size

    if len(wire) < 12:
        raise ValueError("truncated DNS header")
    questions, answers = struct.unpack_from("!HH", wire, 4)
    offset = 12
    for _ in range(questions):
        offset = skip_name(offset, True) + 4
        if offset > len(wire):
            raise ValueError("truncated question")
    targets = 0
    for _ in range(answers):
        offset = skip_name(offset, True)
        if offset + 10 > len(wire):
            raise ValueError("truncated record")
        rtype, _, _, length = struct.unpack_from("!HHIH", wire, offset)
        offset += 10
        end = offset + length
        if end > len(wire):
            raise ValueError("truncated RDATA")
        if rtype == 39:
            if skip_name(offset, False) != end:
                raise ValueError("invalid DNAME RDATA length")
            targets += 1
        offset = end
    return targets


def validate_signatures(case, reply, keys):
    import dns.dnssec
    import dns.rdatatype

    data = {
        (rr.name, rr.rdtype): rr
        for rr in reply.answer
        if rr.rdtype != dns.rdatatype.RRSIG
    }
    signed = set()
    for rr in reply.answer:
        if rr.rdtype != dns.rdatatype.RRSIG:
            continue
        for sig in rr:
            key = (rr.name, sig.type_covered)
            assert key in data, "unmatched RRSIG"
            dns.dnssec.validate_rrsig(data[key], sig, keys)
            signed.add(key)
    for key, rr in data.items():
        # DNAME synthesis creates an unsigned CNAME at the expanded owner.
        synthesized = rr.rdtype == dns.rdatatype.CNAME and any(
            dname.rdtype == dns.rdatatype.DNAME
            and rr.name != dname.name
            and rr.name.is_subdomain(dname.name)
            and len(dname) == 1
            and len(rr) == 1
            and rr[0].target
            == rr.name.relativize(dname.name).concatenate(dname[0].target)
            for dname in data.values()
        )
        if synthesized:
            assert key not in signed, "synthesized CNAME unexpectedly signed"
        else:
            assert key in signed, f"missing signature for {key} in {case[0]}"
    if case[0] == "owner-missing":
        nsecs = [
            rr
            for rr in reply.authority
            if rr.rdtype == dns.rdatatype.NSEC and rr.name.to_text().lower() == case[1]
        ]
        assert len(nsecs) == 1 and len(nsecs[0]) == 1, "missing exact-owner NSEC"
        nsec = next(iter(nsecs[0]))
        assert all(
            not (window == 0 and len(bits) > 0 and bits[0] & mask)
            for window, bits in nsec.windows
            for mask in (0x40, 0x04)
        ), "NSEC claims A or CNAME"
        assert any(
            window == 0 and len(bits) > 4 and bits[4] & 1
            for window, bits in nsec.windows
        ), "NSEC omits DNAME"
        for rr in reply.authority:
            if rr.rdtype not in (dns.rdatatype.NSEC, dns.rdatatype.SOA):
                continue
            sigs = [
                candidate
                for candidate in reply.authority
                if candidate.rdtype == dns.rdatatype.RRSIG
                and candidate.name == rr.name
                and candidate.covers == rr.rdtype
            ]
            assert len(sigs) == 1, "missing denial signature"
            dns.dnssec.validate(rr, sigs[0], keys)


def signed_fault_tests(host, port, keys):
    import dns.flags
    import dns.message
    import dns.query
    import dns.rdatatype
    import dns.rrset

    def response(case):
        query = dns.message.make_query(case[1], case[2], want_dnssec=True, payload=1232)
        query.flags &= ~dns.flags.RD
        result = dns.query.tcp(query, host, port=port, timeout=3)
        assert query.is_response(result)
        validate_signatures(case, result, keys)
        return result

    def reject(case, reply):
        try:
            validate_signatures(case, reply, keys)
        except Exception:
            return
        raise AssertionError("signed fault accepted")

    positive = next(case for case in cases() if case[0] == "local-cname")
    valid = response(positive)
    missing = copy.deepcopy(valid)
    missing.answer = [
        rr
        for rr in missing.answer
        if not (rr.rdtype == dns.rdatatype.RRSIG and rr.covers == dns.rdatatype.DNAME)
    ]
    reject(positive, missing)
    changed = copy.deepcopy(valid)
    for index, rr in enumerate(changed.answer):
        if rr.rdtype == dns.rdatatype.DNAME:
            changed.answer[index] = dns.rrset.from_text(
                rr.name, rr.ttl, "IN", "DNAME", "wrong.example.test."
            )
    reject(positive, changed)
    changed = copy.deepcopy(valid)
    for index, rr in enumerate(changed.answer):
        if rr.rdtype == dns.rdatatype.CNAME:
            changed.answer[index] = dns.rrset.from_text(
                rr.name, rr.ttl, "IN", "CNAME", "wrong.example.test."
            )
    reject(positive, changed)
    negative = next(case for case in cases() if case[0] == "owner-missing")
    valid = response(negative)
    missing = copy.deepcopy(valid)
    missing.authority = [
        rr for rr in missing.authority if rr.rdtype != dns.rdatatype.NSEC
    ]
    reject(negative, missing)
    missing = copy.deepcopy(valid)
    missing.authority = [
        rr
        for rr in missing.authority
        if not (rr.rdtype == dns.rdatatype.RRSIG and rr.covers == dns.rdatatype.NSEC)
    ]
    reject(negative, missing)
    print(json.dumps({"signed_fault_tests": 5, "passed": True}), flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--server", type=endpoint, required=True)
    parser.add_argument("--repeats", type=int, default=40)
    parser.add_argument("--signed", action="store_true")
    parser.add_argument("--signed-fault-tests", action="store_true")
    args = parser.parse_args()
    if args.repeats < 1:
        parser.error("positive repeat count required")
    import dns.flags
    import dns.message
    import dns.query
    import dns.rdataclass
    import dns.rdatatype

    if args.signed:
        import dns.name
        import dns.zone

        apex = dns.name.from_text("example.test.")
        zone = dns.zone.from_file(
            "/work/dname-signed.db", origin=apex, relativize=False
        )
        keys = {apex: zone.get_rdataset(apex, dns.rdatatype.DNSKEY)}
    label, host, port = args.server
    if args.signed_fault_tests:
        if not args.signed:
            parser.error("--signed-fault-tests requires --signed")
        signed_fault_tests(host, port, keys)
        return
    for protocol in ("udp", "tcp"):
        for case in cases():
            query = dns.message.make_query(
                case[1], case[2], use_edns=0, payload=1232, want_dnssec=args.signed
            )
            query.flags &= ~dns.flags.RD
            observed = None
            error = None
            try:
                for _ in range(args.repeats):
                    reply = getattr(dns.query, protocol)(
                        query, host, port=port, timeout=3
                    )
                    assert query.is_response(reply), "uncorrelated response"
                    assert all(
                        rr.rdclass == dns.rdataclass.IN
                        for rr in reply.answer + reply.authority
                    ), "wrong class"
                    assert uncompressed_dname_targets(reply.wire) == sum(
                        rr.rdtype == dns.rdatatype.DNAME for rr in reply.answer
                    ), "DNAME wire check"
                    if args.signed:
                        validate_signatures(case, reply, keys)
                    observed = {
                        "rcode": reply.rcode(),
                        "aa": bool(reply.flags & dns.flags.AA),
                        "tc": bool(reply.flags & dns.flags.TC),
                        "answer": [
                            (
                                rr.name.to_text().lower(),
                                dns.rdatatype.to_text(rr.rdtype),
                                item.to_text().lower(),
                                rr.ttl,
                            )
                            for rr in reply.answer
                            if rr.rdtype != dns.rdatatype.RRSIG
                            for item in rr
                        ],
                        "soa": [
                            (rr.name.to_text().lower(), rr.ttl)
                            for rr in reply.authority
                            if rr.rdtype == dns.rdatatype.SOA
                        ],
                    }
                    validate(case, observed)
            except Exception as exc:
                error = str(exc) or repr(exc)
            print(
                json.dumps(
                    {
                        "server": label,
                        "protocol": protocol,
                        "case": case[0],
                        "checks": args.repeats if error is None else 0,
                        "passed": error is None,
                        "error": error,
                        "observed": observed,
                    }
                ),
                flush=True,
            )


if __name__ == "__main__":
    main()
